 "content": "def transform(grid):
    if not grid:
        return []
    from collections import Counter
    counts = Counter(v for row in grid for v in row)
    background = counts.most_common(1)[0][0]
    marker_counts = Counter()
    for row in grid:
        for c in range(len(row)-1):
            if row[c] != background and row[c+1] == background:
                marker_counts[row[c]] += 1
            elif row[c] == background and row[c+1] != background:
                marker_counts[row[c+1]] += 1
    marker = marker_counts.most_common(1)[0][0] if marker_counts else background
    out = [row[:] for row in grid]
    for r, row in enumerate(grid):
        for c in range(1, len(row)-1):
            if row[c] == background and row[c-1] == row[c+1] == marker:
                out[r][c] = 2
    return out

