        for c in cs:d2[r][c]=0
    e2=[row[:] for row in d2]
    for r,row in enumerate(d2):
        for c in range(1,11):
            if row[c]==8 and row[c-1]==row[c+1]==0:e2[r][c]=2
    assert transform(d2)==e2
    d3=[[6]*9 for _ in range(5)]
    for r,cs in {0:[0,2],2:[2,4,6]}.items():
        for c in cs:d3[r][c]=8
    e3=[row[:] for row in d3]
    for r,row in enumerate(d3):
        for c in range(1,8):
            if row[c]==6 and row[c-1]==row[c+1]==8:e3[r][c]=2
    assert transform(d3)==e3
    d4=[[9]*10 for _ in range(7)]
    for r,cs in {0:[1,3],1:[1,3,5,7],2:[1,3],4:[0,2],6:[0,2]}.items():
